#![allow(dead_code)]

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Rarity {
    Common,
    Uncommon,
    Rare,
    Epic,
}

impl Rarity {
    pub fn color(self) -> u32 {
        match self {
            Rarity::Common => 0xFFFFFF,
            Rarity::Uncommon => 0xFFFF55,
            Rarity::Rare => 0x55FFFF,
            Rarity::Epic => 0xFF55FF,
        }
    }
}

pub struct ItemDef {
    pub id: &'static str,
    pub name: &'static str,
    pub max_stack: u8,
    pub max_damage: u16,
    pub rarity: Rarity,
    pub is_block: bool,
}

