pub fn item(id: &str) -> Option<&'static ItemDef> {
    ITEMS
        .binary_search_by_key(&id, |d| d.id)
        .ok()
        .map(|i| &ITEMS[i])
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TabRow {
    Top,
    Bottom,
}

pub struct CreativeTab {
    pub id: &'static str,
    pub title: &'static str,
    pub icon: &'static str,
    pub row: TabRow,
    pub column: u8,
    pub items: &'static [&'static str],
}

